from collections import deque
from random import Random


SMALL_CASES = (
    (2, 1, (0, 0), (0, 0), (1, 2), (2, 1)),
    (2, 2, (0, 1), (0, 1), (2, 1), (1, 2)),
    (2, 2, (1, 0), (0, 0), (1, 2), (2, 1)),
    (2, 2, (1, 0), (1, 0), (2, 1), (2, 1)),
    (3, 3, (1, 1, 1), (1, 1, 1), (2, 3, 1), (3, 1, 2)),
    (4, 1, (0, 0, 1, 0), (0, 0, 0, 0), (2, 1, 4, 3), (1, 2, 3, 4)),
    (3, 1, (0, 0, 0), (0, 1, 1), (1, 2, 3), (1, 3, 2)),
    (5, 3, (0, 1, 0, 1, 0), (0, 0, 1, 0, 1), (4, 1, 2, 3, 5), (3, 4, 5, 2, 1)),
)


def _integer(token):
    digits = token[1:] if token.startswith(("+", "-")) else token
    if not digits.isascii() or not digits.isdecimal():
        raise ValueError("expected a decimal integer")
    significant = digits.lstrip("0")
    if len(significant) > 6:
        raise OverflowError("integer exceeds the magnitude of all legal values")
    value = int(significant or "0")
    return -value if token.startswith("-") else value


def _parse(inp):
    tokens = inp.split()
    if len(tokens) < 2:
        return None
    try:
        size, target = map(_integer, tokens[:2])
        if not 2 <= size <= 200_000 or not 1 <= target <= size:
            return None
        if len(tokens) != 2 + 4 * size:
            return None
        red, blue, p, q = (
            tuple(map(_integer, tokens[start:start + size]))
            for start in range(2, len(tokens), size)
        )
    except (ValueError, OverflowError):
        return None

    if any(value not in (0, 1) for row in (red, blue) for value in row):
        return None
    for permutation in (p, q):
        if any(value < 1 or value > size for value in permutation):
            return None
        if len(set(permutation)) != size:
            return None
    return size, target, red, blue, p, q


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def _format(size, target, red, blue, p, q):
    rows = ((size, target), red, blue, p, q)
    return "\n".join(" ".join(map(str, row)) for row in rows) + "\n"


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = []
    for index in range(n):
        if index < len(SMALL_CASES):
            cases.append(_format(*SMALL_CASES[index]))
            continue
        size = rng.randint(2, 5)
        target = rng.randint(1, size)
        p = list(range(1, size + 1))
        q = p.copy()
        rng.shuffle(p)
        rng.shuffle(q)
        red = [rng.randrange(2) for _ in range(size)]
        blue = [rng.randrange(2) for _ in range(size)]
        cases.append(_format(size, target, red, blue, p, q))
    return cases


def _set_cycle(permutation, boxes):
    for index, box in enumerate(boxes):
        permutation[box - 1] = boxes[(index + 1) % len(boxes)]


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    size = 200_000
    boxes = list(range(1, size + 1))
    rng.shuffle(boxes)
    target = boxes[0]
    red = [1] * size
    blue = [1] * size
    p = [0] * size
    q = [0] * size
    _set_cycle(p, boxes)
    _set_cycle(q, boxes[::-1])
    opposite_cycles = _format(size, target, red, blue, p, q)

    _set_cycle(q, boxes[:-2])
    _set_cycle(q, boxes[-2:])
    blue[boxes[-1] - 1] = 0
    separate_blue_cycle = _format(size, target, red, blue, p, q)
    return [opposite_cycles, separate_blue_cycle]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    case = _parse(inp)
    if case is None:
        return [("POST-1", "Input violates the specified preconditions.")]
    size, target, red, blue, p, q = case

    tokens = out.split()
    if len(tokens) != 1:
        return [("POST-2", "Expected exactly one integer token.")]
    try:
        answer = _integer(tokens[0])
    except ValueError:
        return [("POST-2", "Expected a decimal integer token.")]
    except OverflowError:
        return [("POST-2", "Answer is outside the allowed range.")]
    if answer != -1 and not 0 <= answer <= 2 * (size - 1):
        return [("POST-2", "Answer is outside the allowed range.")]

    occupied_outside = sum(
        bool(a or b)
        for box, (a, b) in enumerate(zip(red, blue), 1)
        if box != target
    )
    if occupied_outside == 0:
        if answer != 0:
            return [("POST-4", "The initial state already meets the goal.")]
        return []

    violations = []
    if 0 <= answer < occupied_outside:
        violations.append(
            ("POST-4", "Each initially occupied box outside X must be operated on.")
        )

    if answer >= 0:
        for color, counts, permutation in (("Red", red, p), ("Blue", blue, q)):
            target_fixed = permutation[target - 1] == target
            if any(
                count and box != target and (target_fixed or destination == box)
                for box, (count, destination) in enumerate(zip(counts, permutation), 1)
            ):
                violations.append(
                    ("POST-5", f"{color} contains a ball that cannot reach X.")
                )
    return violations


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for index, original in enumerate(gen_small(seed, n)):
        size, target, red, blue, p, q = _parse(original)
        if index % 2 == 0 and (red != blue or p != q):
            transformed = _format(size, target, blue, red, q, p)
        else:
            labels = list(range(1, size + 1))
            rng.shuffle(labels)
            target_index = target - 1
            if labels[target_index] == target:
                other = (target_index + 1) % size
                labels[target_index], labels[other] = labels[other], labels[target_index]
            new_red = [0] * size
            new_blue = [0] * size
            new_p = [0] * size
            new_q = [0] * size
            for old_index, new_label in enumerate(labels):
                new_index = new_label - 1
                new_red[new_index] = red[old_index]
                new_blue[new_index] = blue[old_index]
                new_p[new_index] = labels[p[old_index] - 1]
                new_q[new_index] = labels[q[old_index] - 1]
            transformed = _format(
                size, labels[target_index], new_red, new_blue, new_p, new_q
            )
        pairs.append(("POST-3", "equal", original, transformed))
    return pairs


def reference_small(inp: str) -> str | None:
    case = _parse(inp)
    if case is None:
        return None
    size, target, red, blue, p, q = case
    if size > 5:
        return None

    target_index = target - 1
    outside = tuple(box for box in range(size) if box != target_index)
    initial = red + blue
    pending = deque([(initial, 0)])
    seen = {initial}

    while pending:
        state, operations = pending.popleft()
        if all(state[box] == 0 and state[size + box] == 0 for box in outside):
            return str(operations)

        for box in range(size):
            red_count = state[box]
            blue_count = state[size + box]
            if red_count == 0 and blue_count == 0:
                continue
            moved = list(state)
            moved[box] = 0
            moved[size + box] = 0
            moved[p[box] - 1] += red_count
            moved[size + q[box] - 1] += blue_count
            next_state = tuple(moved)
            if next_state not in seen:
                seen.add(next_state)
                pending.append((next_state, operations + 1))

    return "-1"
